(window.webpackJsonp=window.webpackJsonp||[]).push([[164],{492:function(_,v,a){"use strict";a.r(v);var t=a(7),r=function(_){_.options.__data__block__={mermaid_64a570e2:'graph TB\n    M["英格兰煤矿的木轨<br/>马拉煤车，宽度互不统一"] --\x3e S["斯蒂芬森 1826<br/>轨距加宽半英寸<br/>4 英尺 8.5 英寸 = 1435 mm"]\n    S --\x3e R["1845 皇家委员会<br/>1846 年《铁路轨距条例》"]\n    R --\x3e G["大西部铁路 1892 年改轨<br/>轨距战争结束"]\n    G --\x3e W["随帝国与资本扩散<br/>美国、殖民地、中国"]\n    W --\x3e UIC["1937 国际铁路协会<br/>1435 mm 成为国际标准"]\n    R -.->|"1842 沙皇否决<br/>选了 5 英尺"| RU["俄罗斯 1520 mm<br/>1520 俱乐部"]\n    UIC --\x3e C["ISO 668 集装箱 8 英尺宽"]\n    RU --\x3e B["中俄边境 85 mm<br/>换装 / 换转向架"]\n    UIC --\x3e B\n'}},e=Object(t.a)({},(function(){var _=this,v=_.$createElement,a=_._self._c||v;return a("ContentSlotsDistributor",{attrs:{"slot-key":_.$parent.slotKey}},[a("p",[_._v("先说结论：全世界大约 60% 的铁路，两条钢轨内侧之间的距离是 1435 毫米。这个数字很怪，不像算出来的，倒像是有人拍脑袋定的，然后所有人都不敢改。")]),_._v(" "),a("p",[_._v("关于它怎么来的，有一个流传了一百多年的故事，顺得像一段设计好的谜语：")]),_._v(" "),a("blockquote",[a("p",[_._v("1435 毫米 = 4 英尺 8.5 英寸。这个奇怪的英制尺寸来自古罗马。罗马战车的宽度是两匹马并排的宽度，也就是两个马屁股的宽度。罗马人用它铺石板路，石板路上压出了两道车辙。两千年来英国的马车就沿着这两道辙跑，轮距被锁死成 4 英尺 8.5 英寸。铁路出现时照抄了马车的轮距。铁路传到美国，美国又照抄英国。后来航天飞机要坐火车穿过犹他州的隧道，助推器的直径因此也被两匹马屁股锁死。")])]),_._v(" "),a("p",[_._v("这个故事讲得真好。环环相扣，最后落在一个荒诞又好笑的结论上：全世界最先进的运输系统，是两千年前两匹马屁股的宽度决定的。")]),_._v(" "),a("p",[_._v("它还常被当证据用，证明「标准」和「路径依赖」这两件事。")]),_._v(" "),a("p",[_._v("可惜，这段故事基本上是假的。")]),_._v(" "),a("h2",{attrs:{id:"一、一个段子的三个漏洞"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#一、一个段子的三个漏洞"}},[_._v("#")]),_._v(" 一、一个段子的三个漏洞")]),_._v(" "),a("p",[_._v("先说最容易被戳穿的一环：罗马战车。")]),_._v(" "),a("p",[_._v("古罗马的战车（biga、quadriga）确实由两匹或四匹马牵引。但战车车轴的宽度是按乘员和战斗需要设计的，不是按马的臀宽设计的。梵蒂冈博物馆里那尊被认为最接近真实战车的 Franzoni 雕塑可以看出来：如果把四匹马里最外侧的两匹去掉，只剩两匹的双马战车（biga），它的车轴依然比两匹马并排的宽度要宽。战车本来就比马背之间的空档要宽，不然车轮和车体就摆不下了。")]),_._v(" "),a("p",[_._v("换句话说，「战车宽度 = 马屁股宽度」在几何上就不成立。")]),_._v(" "),a("p",[_._v('第二环是车辙。英格兰那些"古罗马石板路车辙"，考古证据更支持它们是给更窄的手推车压出来的，而不是给战车。历史学者 D. Gabe Gabriel 在考据这件事时发现，这个说法的流传版本很可能是二战后才定型并扩散的，而战前的史料不支持它。Snopes 查过之后给的判断是"假"——但同时补了一句挺妙的：也许更公允的说法是"部分为真，但真实原因平凡得不值一提"。')]),_._v(" "),a("p",[_._v("第三环是最当代的那一环：航天飞机。")]),_._v(" "),a("p",[_._v('故事说 NASA 的固体助推器（SRB）直径被犹他州到佛罗里达那条铁路上的隧道卡住了。这件事的现实版本是：SRB 直径 3.71 米（12.17 英尺），确实是从犹他州 Thiokol 的工厂分 4 段、每段 32 英尺长、约 150 吨，用火车运到肯尼迪航天中心的。为此 NASA 专门买下并重修了佛罗里达东海岸铁路的一段，那条 38 英里的"NASA Railroad"今天还在跑。')]),_._v(" "),a("p",[_._v("但真正卡住它的是"),a("strong",[_._v("装载限界")]),_._v("（loading gauge），也就是车厢能装多高多宽的东西，而不是轨距。轨距和装载限界只是间接相关：铁轨窄，车架就要窄，隧道跟着变矮变窄，于是能塞过去的货也就小了。")]),_._v(" "),a("p",[_._v('况且数量级就说不通。SRB 的直径是 12 英尺（3.71 米），而标准轨距只有 4 英尺 8.5 英寸（1.435 米）——前者是后者的两倍半。"隧道只比铁轨宽一点点"这个说法，从一开始就不可能成立。')]),_._v(" "),a("p",[_._v("三个漏洞，一个比一个致命。但真正的源头比传说更平淡，平淡到有点无聊——而无聊，恰恰是标准形成的方式。")]),_._v(" "),a("h2",{attrs:{id:"二、真正的源头-一座煤矿-和半英寸"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#二、真正的源头-一座煤矿-和半英寸"}},[_._v("#")]),_._v(" 二、真正的源头：一座煤矿，和半英寸")]),_._v(" "),a("p",[a("img",{attrs:{src:"/images/2026/11/06/fig-mine.jpeg",alt:"英格兰北部矿区里马拉煤车行驶在木轨上",loading:"lazy"}})]),_._v(" "),a("p",[_._v("19 世纪初的英格兰东北部，纽卡斯尔一带是煤矿腹地。煤矿里运煤靠马拉的煤车，煤车跑在木轨上——这些轨道叫 wagonway，一直可以追溯到 16 世纪的德国矿区，是全世界最早的铁路，只是没有蒸汽机。")]),_._v(" "),a("p",[_._v("这些煤轨的宽度极不统一。原因很朴素：不同矿区之间不共用轨道，谁也没必要跟谁对齐，每个矿想铺多宽就铺多宽。")]),_._v(" "),a("p",[_._v('乔治·斯蒂芬森（George Stephenson）早年在 Killingworth 煤矿干活，被这种混乱折磨够了。他 1814 年的"旅行者号"（Blücher）就是在这种木轨矿道上跑的。')]),_._v(" "),a("p",[_._v('后来他造"火箭号"（Rocket），转战正式铁路。这辆机车的设计细节里有一串很值得盯的尺寸：火箭号的车轴长 5 英尺 4¾ 英寸，动轮厚 8¼ 英寸，扣掉 1 英寸的轮缘，理论上最小轨距是 4 英尺 7¾ 英寸。')]),_._v(" "),a("p",[_._v("斯蒂芬森最初把它定在 4 英尺 8 英寸，比理论下限略宽一点，给车轮留出跑动的余量。但早期火车既没有差速装置也没有转向架，一转弯就噪音巨大、轮轨磨得飞快。1826 年他干了一件很工程师的事：与其重新设计机车，不如把轨距加宽——改轨距比改机车便宜。于是加了半英寸。")]),_._v(" "),a("p",[_._v("4 英尺 8 英寸 + 半英寸 = 4 英尺 8.5 英寸 = 56.5 英寸 × 25.4 = 1435.1 毫米。")]),_._v(" "),a("p",[_._v("再往下一层：这是个为了少磨轮子而临时加的半英寸。但它一旦成为主流，就再也拿不掉了。")]),_._v(" "),a("p",[_._v('顺带说一个数字上的小玩笑：56.5 × 25.4 = 1435.1，不是 1435。国际铁路协会 1937 年把它定为标准时，把那 0.1 毫米扔了。而英国国铁在 1968 年（有些资料写 1977 年）干脆把本国标准轨距重新定义成 1432 毫米——比"标准"还窄 3 毫米，为的是让经过几十年磨耗的钢轨还能塞进这个数字里。香港地铁当年跟着这个定义走，就是现在香港地铁 1432 毫米轨距的来历。')]),_._v(" "),a("h2",{attrs:{id:"三、一场打了十一年的轨距战争"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#三、一场打了十一年的轨距战争"}},[_._v("#")]),_._v(" 三、一场打了十一年的轨距战争")]),_._v(" "),a("p",[_._v('斯蒂芬森的 1435 毫米并没有立刻成为标准。它只是"用的人最多"的那个方案。')]),_._v(" "),a("p",[a("img",{attrs:{src:"/images/2026/11/06/fig-gaugewar.jpeg",alt:"一列宽轨列车和一列窄轨列车在 1840 年代的英国枢纽站交会，旅客在中间换车",loading:"lazy"}})]),_._v(" "),a("p",[_._v('1835 年，伊萨克·金登·布鲁内尔（Isambard Kingdom Brunel）拿到大西部铁路（Great Western Railway）的特许状，他选了 7 英尺 1¼ 英寸（2140 毫米）的宽轨。这个选择在当时看非常聪明：车厢更宽更稳，跑得更快也更容易吸引乘客，布鲁内尔甚至为此设计了漂亮的宽体车厢和"布鲁内尔式"预制梁桥。')]),_._v(" "),a("p",[_._v("但它立刻带来一个致命问题：接不上别人的铁路。布鲁内尔修到西部，与别家的准轨线路一接头就断人、断行李、断货物。商人们抱怨得最凶。")]),_._v(" "),a("p",[_._v('1835 到 1846 年，英国打了十一年的"轨距战争"（Gauge War），被后人称为最早的一次格式之战。1845 年，皇家委员会（Royal Commission on Railway Gauges）开会，成员是 Airy、Barlow 等人，要在 7 英尺的宽轨和 4 英尺 8.5 英寸之间二选一。')]),_._v(" "),a("p",[_._v("结论毫无悬念：4 英尺 8.5 英寸。理由也很朴素——当时英国已经修好的铁路大多已经是这个宽度了，换轨的钱比保留两套系统的钱多得多，而且宽轨能坐更多人并不足以抵消整个网络被撕开的损失。")]),_._v(" "),a("p",[_._v("1846 年 8 月 18 日，《铁路轨距条例》（Railway Regulation (Gauge) Act 1846）颁布：英格兰和威尔士的铁路统一用 4 英尺 8.5 英寸，爱尔兰用 5 英尺 3 英寸。大西部铁路一直拖到 1892 年才彻底改完。")]),_._v(" "),a("Mermaid",{attrs:{id:"mermaid_64a570e2",graph:_.$dataBlock.mermaid_64a570e2}}),a("p",[_._v('这就是路径依赖最干净的一个标本：一个来自一座煤矿的、为了少磨轮子而临时加的半英寸，靠"先来者"的身份赢了一场国家级裁决，然后随着帝国和资本一起出门旅行。')]),_._v(" "),a("p",[a("img",{attrs:{src:"/images/2026/11/06/fig-gauge.jpeg",alt:"一把卷尺拉在两根钢轨之间，量出那个奇怪的距离",loading:"lazy"}})]),_._v(" "),a("p",[_._v("它搭上船去了美国（早期美国铁路的工程师基本是英国人），搭上船去了殖民地，搭上船去了中国。中国最早的铁路之一唐胥铁路由英国人修，轨距就是 1435 毫米。1937 年国际铁路协会正式把 1435 定为国际标准轨距时，它已经覆盖了全球大半。")]),_._v(" "),a("p",[_._v('顺便一提，这个数字后来还决定了很多"看起来跟铁路无关"的东西。ISO 668 把集装箱宽度定为 8 英尺（2438 毫米），理由正是它得同时塞进美国公路的车道宽度限制、以及欧洲铁路的装载限界；而欧洲铁路的装载限界又是跟着标准轨距一路定下来的。全世界跑的集装箱，宽度里其实也掺着一份两匹马屁股的遗产。')]),_._v(" "),a("p",[_._v('日本是个更有意思的例子。这个国家的铁路是从 1067 毫米的窄轨起步的，山区多、窄轨便宜，窄轨窄轨一路窄到今天仍在跑。可 1964 年东海道新干线开工时，管理层决定另起一条标准轨（1435 毫米）的新线，而不是把原有的窄轨拓宽——结果就是你在东京换乘时，新干线的座位会宽出那么一圈。而在秋田、山形两条"迷你新干线"上，你甚至能看到标准轨和窄轨并排铺在一起，像是把历史的一次妥协直接摆在了路基上。')]),_._v(" "),a("h2",{attrs:{id:"四、岔路-俄罗斯的-1520"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#四、岔路-俄罗斯的-1520"}},[_._v("#")]),_._v(" 四、岔路：俄罗斯的 1520")]),_._v(" "),a("p",[_._v('如果故事到"全世界统一"就结束，也就没意思了。真正的戏剧性在于，有人明确地拒绝了它。')]),_._v(" "),a("p",[_._v("1842 年，沙皇尼古拉一世批准圣彼得堡到莫斯科的铁路（后来的尼古拉铁路），标准由工程师 Mel'nikov 主持选定。他挑的是 5 英尺，即 1524 毫米，比标准轨整整宽出 89 毫米。")]),_._v(" "),a("p",[_._v("理由有两层。工程层面：更宽的轨距在重载和高速下更稳，装载限界也更宽松。战略层面，这个说法流传最广的版本是：宽轨是一道国防线，入侵者的军列开不进来，补给线接不上。苏联时期把 1524 微调成 1520（窄 4 毫米，方便车轮与轨道的磨损管理），沿用至今。")]),_._v(" "),a("p",[_._v('这道"国防线"在二战时确实兑现过：德军装甲部队推进极快，但进了苏联境内铁路立刻趴窝，占领区的 1520 宽轨要一段段改成德国标准，后勤崩溃。当然也有更冷静的说法：俄国军方 1841 年就意识到，破坏铁路靠炸桥炸隧道比靠轨距差更有效。')]),_._v(" "),a("p",[_._v('不管动机是什么，结果是今天俄罗斯、白俄罗斯、乌克兰、哈萨克斯坦、蒙古、乌兹别克斯坦……组成了一个"1520 俱乐部"，占全球铁路里程约 18%，只在内部互相兼容。')]),_._v(" "),a("h2",{attrs:{id:"五、那-85-毫米-现在还在收过路费"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#五、那-85-毫米-现在还在收过路费"}},[_._v("#")]),_._v(" 五、那 85 毫米，现在还在收过路费")]),_._v(" "),a("p",[_._v("标准轨 1435 与俄式宽轨 1520，差 85 毫米，5.9%。听起来微不足道，但两套钢轨之间的距离差了这 85 毫米，车就是过不去。")]),_._v(" "),a("p",[a("img",{attrs:{src:"/images/2026/11/06/fig-border.jpeg",alt:"边境换装场：龙门吊把集装箱从准轨车吊到宽轨车上",loading:"lazy"}})]),_._v(" "),a("p",[_._v("于是有了中欧班列在边境上的一系列动作：在满洲里、后贝加尔斯克、阿拉山口、二连浩特这些口岸，集装箱被龙门吊整体吊起来，从准轨平板车挪到宽轨平板车上；或者整节车厢被液压顶起约一米高，底下那整套带轮子的架子（转向架）被换成另一种轨距的。坐国际列车的旅客则是换转向架，人不下车。")]),_._v(" "),a("p",[_._v('早期是"倒装"：一列 40 到 50 节车厢，卸货再装货，一次 6 到 8 小时，旺季轮班 24 小时。现在换装技术好多了，二连浩特的室内换装库能把单列集装箱换装压到 1.5 到 3 小时，但仍然是一道必须在场、无法绕过的工序。零下三十度的冬天，换转向架和吊装都会明显变慢——这条通道最糟的月份不是 12 月，是 1 月。')]),_._v(" "),a("p",[_._v("代价有多具体？满洲里一侧日处理能力约 840 个标准箱，后贝加尔斯克长期卡在约 600，差近三分之一。2025 年初积压的集装箱一度超过 3200 个，换装周期被拉长到 7 到 14 天。")]),_._v(" "),a("p",[_._v("还有一层更贵的账：轨距差一点点，货车车厢的横截面就差一截。同样把车体总宽定死的前提下，宽轨能多装的货更多——按 1520 与 1435 的比例算，横截面积差 12%。这 12% 是全世界的硬通货在某个边界上被反复摩擦掉的一部分。")]),_._v(" "),a("h2",{attrs:{id:"六、10-公里"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#六、10-公里"}},[_._v("#")]),_._v(" 六、10 公里")]),_._v(" "),a("p",[_._v("2026 年 5 月 20 日，北京。中俄两国政府签署《关于共同建设后贝加尔斯克—满洲里跨境铁路 1435 毫米轨距二线的协定》。10 月 15 日，俄罗斯国家杜马全体会议 420 票赞成、零反对、零弃权通过；10 月 28 日联邦委员会批准；11 月 2 日普京签署法律。")]),_._v(" "),a("p",[_._v("全部内容是：在俄罗斯后贝加尔斯克口岸站场范围内，新铺大约十公里 1435 毫米的第二主线。俄罗斯自己那套 1520 宽轨，一根钢轨都不动。")]),_._v(" "),a("p",[_._v("为这十公里，俄罗斯走完了完整的立法程序：下院全票、上院通过、总统签字。俄媒把这当成本国铁路史上少见的事件。保守派在审议时的反对理由也很直白：宽轨从沙俄时代起就是一套刻意与欧洲错开的轨距体系，让外国轨距进入俄罗斯领土，哪怕只是一段站场轨道，触碰的是主权符号。")]),_._v(" "),a("p",[_._v("而这十公里对应的现实是：后贝加尔斯克是整条中俄东线通道最窄的卡口，它比满洲里少处理三分之一的货，旺季就是堵点。")]),_._v(" "),a("p",[_._v('一件工程决定，用了三个国家的立法程序、一次真正的国家元首签署，来处理 85 毫米的差距。这大概是"路径依赖"这四个字最现代的一次注释。')]),_._v(" "),a("p",[a("img",{attrs:{src:"/images/2026/11/06/fig-rome.jpeg",alt:"一条古罗马石板路，石板上有深深的车辙",loading:"lazy"}})]),_._v(" "),a("h2",{attrs:{id:"尾声"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#尾声"}},[_._v("#")]),_._v(" 尾声")]),_._v(" "),a("p",[_._v('回头看，那个流传了一百年的"马屁股"段子，其实讲对了最重要的一件事，只是不是它以为的那件。')]),_._v(" "),a("p",[_._v('它以为轨距是一道自然法则被文明误解了。真相是：轨距是一次路径依赖的胜利，靠先来者的既得利益和英国议会的一纸法案凝固下来，然后靠帝国、资本、战争和一次次"就这么定了"传播开。它不是自然法则，它是历史的具体形状——是煤矿、是半英寸、是 1845 年那个委员会里没人想再折腾一次。')]),_._v(" "),a("p",[_._v("而那个段子之所以流传一百多年，是因为它太好记、太顺、太适合当结尾。一段流传度高的解释会反过来占据人们的想象力，真实的那段反而没人记得。这大概也算一种路径依赖，只不过这次锁住的是叙事，不是铁轨。")]),_._v(" "),a("p",[_._v("下次站在站台上，低头看看那两条钢轨。它们相距 1435 毫米，这个距离铺在全球六成的铁路上。而这个数字背后站着的，是一匹马的半个屁股。")])],1)}),[],!1,null,null,null);"function"==typeof r&&r(e);v.default=e.exports}}]);